    '{n, plural, =1{# could not be answered on every page because nothing tells it apart from other elements.} other{# could not be answered on every page because nothing tells them apart from other elements.}}' => '{n, plural, =1{# no se pudo responder en todas las páginas porque nada lo distingue de otros elementos.} other{# no se pudieron responder en todas las páginas porque nada los distingue de otros elementos.}}',
    'Remove scan data' => 'Eliminar datos del análisis',
    '{n, plural, =1{Remove the scan data for this page?} other{Remove the scan data for these # pages?}}' => '{n, plural, =1{¿Eliminar los datos del análisis de esta página?} other{¿Eliminar los datos del análisis de estas # páginas?}}',
    'Remove the scan data for the selected pages?' => '¿Eliminar los datos del análisis de las páginas seleccionadas?',
    'Their scores, issues and scan history are deleted and cannot be brought back. A page that can still be scanned comes back on its next scan, so exclude it under Settings → Scanning first if it should stay out.' => 'Sus puntuaciones, incidencias e historial de análisis se eliminan y no se pueden recuperar. Una página que todavía se puede analizar vuelve en su próximo análisis, así que exclúyala antes en Ajustes → Análisis si debe quedarse fuera.',
    '{n, plural, =1{Removed the scan data for # page.} other{Removed the scan data for # pages.}}' => '{n, plural, =1{Se eliminaron los datos del análisis de # página.} other{Se eliminaron los datos del análisis de # páginas.}}',
    'Readability' => 'Legibilidad',
    'Readability analysis' => 'Análisis de legibilidad',
    'Readability Preview' => 'Vista previa de legibilidad',
    'Readability report' => 'Informe de legibilidad',
